import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#world');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x9bcbd2); scene.fog=new THREE.FogExp2(0x9bcbd2,.00068);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,2200);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
scene.add(new THREE.HemisphereLight(0xc9f0ff,0x89724d,2.1));
const sun=new THREE.DirectionalLight(0xffe6b7,2.8);sun.position.set(-260,380,150);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-230;sun.shadow.camera.right=230;sun.shadow.camera.top=230;sun.shadow.camera.bottom=-230;scene.add(sun);
const mat=(color,roughness=.85,extra={})=>new THREE.MeshStandardMaterial({color,roughness,...extra});
const groundMat=mat(0xffffff,.95,{vertexColors:true});
const worldSize=1500, segments=180;
function heightAt(x,z){const h=(a,b)=>Math.sin(a*.006+b*.004)*Math.cos(b*.008-a*.003);const ridge=Math.max(0,h(x+170,z-80)-.22);return 4+10*h(x,z)+7*Math.sin(x*.014)*Math.sin(z*.012)+ridge*30+Math.max(0,Math.sin((x+z)*.002)-.72)*20;}
const positions=[],colors=[],indices=[];
for(let iz=0;iz<=segments;iz++){for(let ix=0;ix<=segments;ix++){const x=(ix/segments-.5)*worldSize,z=(iz/segments-.5)*worldSize,y=heightAt(x,z);positions.push(x,y,z);let c;if(y>29)c=new THREE.Color('#718277');else if(y>21)c=new THREE.Color('#778f75');else c=new THREE.Color('#83a974');let shade=.93+Math.sin(x*.04+z*.016)*.045;c.multiplyScalar(shade);colors.push(c.r,c.g,c.b);if(ix<segments&&iz<segments){const a=iz*(segments+1)+ix,b=a+1,d=a+segments+1,e=d+1;indices.push(a,d,b,b,d,e);}}}
const terrainGeo=new THREE.BufferGeometry();terrainGeo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));terrainGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));terrainGeo.setIndex(indices);terrainGeo.computeVertexNormals();const terrain=new THREE.Mesh(terrainGeo,groundMat);terrain.receiveShadow=true;scene.add(terrain);
// Rivers and mountain lake, laid into the valley floor.
const waterMat=new THREE.MeshStandardMaterial({color:0x50aab1,roughness:.27,metalness:.08,transparent:true,opacity:.83,emissive:0x14505a,emissiveIntensity:.18});
function makeRiver(points,width){const verts=[],idx=[];for(let i=0;i<points.length;i++){let p=points[i],prev=points[Math.max(0,i-1)],next=points[Math.min(points.length-1,i+1)],dx=next[0]-prev[0],dz=next[1]-prev[1],l=Math.hypot(dx,dz)||1,nx=dz/l,nz=-dx/l,y=heightAt(p[0],p[1])+1.4;verts.push(p[0]+nx*width/2,y,p[1]+nz*width/2,p[0]-nx*width/2,y,p[1]-nz*width/2);if(i<points.length-1){const a=i*2;idx.push(a,a+2,a+1,a+1,a+2,a+3)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex(idx);g.computeVertexNormals();const m=new THREE.Mesh(g,waterMat);m.receiveShadow=true;scene.add(m)}
const river=[];for(let i=0;i<=70;i++){let z=590-i*17,x=80+Math.sin(i*.17)*120+Math.sin(i*.055)*100;river.push([x,z])}makeRiver(river,30);
const lake=new THREE.Mesh(new THREE.CircleGeometry(92,64),waterMat);lake.rotation.x=-Math.PI/2;lake.position.set(-285,heightAt(-285,-105)+2,-105);lake.scale.set(1.35,.8,1);scene.add(lake);
// distant pale mountain silhouettes
for(let i=0;i<25;i++){const a=i/25*Math.PI*2,r=620+Math.random()*180,x=Math.cos(a)*r,z=Math.sin(a)*r;const peak=new THREE.Mesh(new THREE.ConeGeometry(60+Math.random()*65,105+Math.random()*120,6),mat(i%2?'#91a7a3':'#a7b9b1'));peak.position.set(x,27,z);peak.rotation.y=Math.random()*2;scene.add(peak)}
const treeMat=mat('#3f7055'),treeLit=mat('#5f885d'),trunkMat=mat('#73553e');
function addTree(x,z,s=1){const g=new THREE.Group();const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.7*s,1*s,7*s,6),trunkMat);trunk.position.y=3.5*s;trunk.castShadow=true;g.add(trunk);for(let n=0;n<3;n++){const crown=new THREE.Mesh(new THREE.ConeGeometry((4.3-n*.55)*s,(8-n)*s,7),n===1?treeLit:treeMat);crown.position.y=(7+n*2.7)*s;crown.castShadow=true;g.add(crown)}g.position.set(x,heightAt(x,z),z);scene.add(g);return g}
for(let i=0;i<480;i++){const x=(Math.random()-.5)*1280,z=(Math.random()-.5)*1280;if(Math.hypot(x,z)<130||Math.abs(x)<60&&z>100)continue;if(heightAt(x,z)<24)addTree(x,z,.65+Math.random()*.85)}
const buildings=[];
function house(x,z,scale=1,roof='#995b49'){const g=new THREE.Group(),y=heightAt(x,z);const base=new THREE.Mesh(new THREE.BoxGeometry(15*scale,9*scale,12*scale),mat('#e2c99e'));base.position.y=4.5*scale;base.castShadow=true;base.receiveShadow=true;g.add(base);const top=new THREE.Mesh(new THREE.ConeGeometry(11*scale,8*scale,4),mat(roof));top.rotation.y=Math.PI/4;top.position.y=12.8*scale;top.castShadow=true;g.add(top);const door=new THREE.Mesh(new THREE.BoxGeometry(2.5*scale,4.7*scale,.35),mat('#614638'));door.position.set(0,2.4*scale,6.1*scale);g.add(door);g.position.set(x,y,z);scene.add(g);buildings.push(g)}
const villages=[{x:155,z:95,name:'SUNMEADOW'},{x:-385,z:210,name:'MILLHAVEN'},{x:250,z:-335,name:'WILLOWMERE'},{x:470,z:300,name:'THISTLECROSS'}];
for(const v of villages){for(let i=0;i<7;i++)house(v.x+(Math.random()-.5)*75,v.z+(Math.random()-.5)*65,.68+Math.random()*.38,['#a86650','#8d6652','#b77a57'][i%3]);const tower=new THREE.Mesh(new THREE.CylinderGeometry(3,4,22,8),mat('#d6c49d'));tower.position.set(v.x+18,heightAt(v.x+18,v.z)+11,v.z-14);tower.castShadow=true;scene.add(tower);const roof=new THREE.Mesh(new THREE.ConeGeometry(5,8,8),mat('#ad634b'));roof.position.set(v.x+18,heightAt(v.x+18,v.z)+26,v.z-14);scene.add(roof)}
// Soft clouds made from clustered low-poly puffs.
const cloudMat=new THREE.MeshStandardMaterial({color:0xf7fbf4,roughness:1,transparent:true,opacity:.78});
for(let i=0;i<32;i++){const cloud=new THREE.Group();const x=(Math.random()-.5)*1300,z=(Math.random()-.5)*1300,y=125+Math.random()*115;for(let j=0;j<5;j++){const puff=new THREE.Mesh(new THREE.IcosahedronGeometry(9+Math.random()*11,1),cloudMat);puff.position.set((j-2)*13,Math.random()*6,Math.random()*8);cloud.add(puff)}cloud.position.set(x,y,z);scene.add(cloud)}

function ellipsoid(parent,color,pos,scale,detail=2){const m=new THREE.Mesh(new THREE.IcosahedronGeometry(1,detail),mat(color,.62));m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;parent.add(m);return m}
function makeDragon(colors={body:'#bd623d',wing:'#e3945b',belly:'#e4b376',horn:'#e8d0a1'}){const g=new THREE.Group();ellipsoid(g,colors.body,[0,0,0],[2.25,1.35,3.8]);ellipsoid(g,colors.belly,[0,-.8,.35],[1.55,.65,2.4]);ellipsoid(g,colors.body,[0,.4,3.1],[1.2,1.05,1.75]);ellipsoid(g,colors.body,[0,.7,4.35],[1.15,.84,1.6]);ellipsoid(g,'#f1c867',[-.53,.92,5.05],[.16,.13,.14],1);ellipsoid(g,'#f1c867',[.53,.92,5.05],[.16,.13,.14],1);ellipsoid(g,'#263536',[-.55,1.02,5.14],[.07,.08,.08],1);ellipsoid(g,'#263536',[.55,1.02,5.14],[.07,.08,.08],1);for(const s of [-1,1]){const horn=ellipsoid(g,colors.horn,[s*.62,1.55,3.95],[.22,.7,.25],1);horn.rotation.z=-s*.35;const ear=ellipsoid(g,colors.body,[s*1.03,1.34,3.55],[.55,.22,.46],1);ear.rotation.z=s*.3;const leg=ellipsoid(g,colors.body,[s*1.05,-1.15,-1.35],[.48,.9,.55]);leg.rotation.z=s*.3;const foot=ellipsoid(g,colors.horn,[s*1.1,-1.65,-1.1],[.55,.22,.6],1);}
// Long segmented silhouette tail with a small diamond fin.
for(let i=0;i<5;i++){const t=i/5,seg=ellipsoid(g,colors.body,[0,-.05,-3.3-i*.78],[1.15*(1-t)+.13,.65*(1-t)+.1,.85],1);seg.rotation.x=-.14}const fin=ellipsoid(g,colors.wing,[0,.28,-7.3],[.85,.18,.65],1);fin.rotation.y=.78;
const wings=[];for(const s of [-1,1]){const pivot=new THREE.Group();pivot.position.set(s*1.5,.7,.15);const shape=new THREE.Shape();shape.moveTo(0,0);shape.lineTo(s*5.2,.25);shape.lineTo(s*4.25,-.6);shape.lineTo(s*3.1,-1.55);shape.lineTo(s*2.7,-.45);shape.lineTo(s*1.4,-1.2);shape.lineTo(s*.8,-.25);shape.lineTo(0,0);const wing=new THREE.Mesh(new THREE.ShapeGeometry(shape),new THREE.MeshStandardMaterial({color:colors.wing,side:THREE.DoubleSide,roughness:.72,transparent:true,opacity:.93}));pivot.add(wing);const boneMat=mat(colors.horn);for(const end of [[s*5.2,.25],[s*4.25,-.6],[s*3.1,-1.55],[s*2.7,-.45],[s*1.4,-1.2]]){const pts=[new THREE.Vector3(0,0,0),new THREE.Vector3(end[0],end[1],0)];const bone=new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts),8,.035,5,false),boneMat);pivot.add(bone)}g.add(pivot);wings.push({pivot,side:s})}
// Saddle and rider silhouette.
ellipsoid(g,'#57463a',[0,1.45,-.05],[.85,.34,1.05],1);ellipsoid(g,'#34434a',[0,2.15,.25],[.52,.72,.48],1);ellipsoid(g,'#cf9b75',[0,2.85,.45],[.42,.43,.42],1);const cloak=ellipsoid(g,'#788d83',[0,2.08,-.28],[.6,.7,.35],1);cloak.rotation.x=-.2;
return {group:g,wings}}
const dragon=makeDragon();scene.add(dragon.group);dragon.group.position.set(0,80,0);
const emberMat=new THREE.MeshStandardMaterial({color:0xf4c870,emissive:0xd54d23,emissiveIntensity:1.5,roughness:.3});
const crystalSpots=[[-285,0,-105],[390,0,-270],[-425,0,390]];
const crystals=[];
for(let i=0;i<crystalSpots.length;i++){const [x,,z]=crystalSpots[i],y=heightAt(x,z);const group=new THREE.Group();const stem=new THREE.Mesh(new THREE.CrystalGeometry?new THREE.CrystalGeometry():new THREE.OctahedronGeometry(4,0),new THREE.MeshStandardMaterial({color:0x83eee0,emissive:0x26bca9,emissiveIntensity:1.3,roughness:.2,metalness:.2}));stem.scale.set(.75,1.8,.75);stem.position.y=6;stem.castShadow=true;group.add(stem);const ring=new THREE.Mesh(new THREE.TorusGeometry(8,.32,6,40),new THREE.MeshBasicMaterial({color:0x84f2dc,transparent:true,opacity:.68}));ring.rotation.x=Math.PI/2;ring.position.y=2;group.add(ring);group.position.set(x,y+1,z);scene.add(group);crystals.push({group,collected:false,base:y})}

