const enemyPositions=[[-165,95,-270],[430,115,125],[-500,140,-125]];
const enemies=enemyPositions.map((p,i)=>{const d=makeDragon({body:'#493d54',wing:'#7a5870',belly:'#887b8d',horn:'#e3a778'});d.group.scale.setScalar(.68);d.group.position.set(p[0],p[1],p[2]);scene.add(d.group);return {dragon:d,alive:true,hp:3,home:new THREE.Vector3(...p),phase:i*2.2}});
const fireballs=[];let collected=0,health=100,stamina=100,heading=0,pitch=0,speed=42,started=false,roarCooldown=0,hitCooldown=0;
const keys={};let mouseX=0,mouseY=0;
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.code==='KeyF')fire();if(e.code==='KeyR')roar()});addEventListener('keyup',e=>keys[e.code]=false);
canvas.addEventListener('pointermove',e=>{if(document.pointerLockElement===canvas){mouseX+=e.movementX;mouseY+=e.movementY}});canvas.addEventListener('click',()=>{if(started&&innerWidth>700&&document.pointerLockElement!==canvas)canvas.requestPointerLock?.()});
function notify(text){const t=document.querySelector('#toast');document.querySelector('#toast-text').textContent=text;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),2800)}
function fire(){if(!started)return;const pos=dragon.group.position.clone().add(new THREE.Vector3(0,.3,4).applyQuaternion(dragon.group.quaternion));const orb=new THREE.Mesh(new THREE.SphereGeometry(1,12,10),emberMat);orb.position.copy(pos);orb.scale.setScalar(1.25);scene.add(orb);const dir=new THREE.Vector3(0,0,1).applyQuaternion(dragon.group.quaternion);fireballs.push({mesh:orb,vel:dir.multiplyScalar(115),life:2.6});const flash=document.querySelector('#combat-flash');flash.classList.remove('show');void flash.offsetWidth;flash.classList.add('show')}
function roar(){if(!started||roarCooldown>0)return;roarCooldown=5;for(const e of enemies){if(e.alive&&e.dragon.group.position.distanceTo(dragon.group.position)<95){e.hp-=2;if(e.hp<=0)defeat(e)}}notify('Sol’s roar echoes across the valley!')}
function defeat(e){e.alive=false;scene.remove(e.dragon.group);notify('A shadowwing has fled! The skies are safer.')}
document.querySelector('#fire-button').onclick=fire;document.querySelector('#roar-button').onclick=roar;document.querySelector('#dragon-call').onclick=()=>notify('Sol answers with a bright, happy chirp.');document.querySelector('#sound-toggle').onclick=()=>notify('The valley’s soundtrack is ready for your imagination.');
document.querySelector('#begin-button').onclick=()=>{started=true;document.querySelector('#start-overlay').classList.add('hidden');notify('Find the glowing emberstones to restore the beacon')};
// Responsive minimap: terrain tint, river, paths, settlements, objectives, rider.
const mapCanvas=document.querySelector('#minimap'),mapCtx=mapCanvas.getContext('2d');
function drawMap(){const w=mapCanvas.width,h=mapCanvas.height;mapCtx.clearRect(0,0,w,h);mapCtx.fillStyle='#647d67';mapCtx.fillRect(0,0,w,h);mapCtx.fillStyle='#738b6a';mapCtx.beginPath();mapCtx.ellipse(w*.5,h*.5,w*.47,h*.43,0,0,Math.PI*2);mapCtx.fill();mapCtx.strokeStyle='#7ed0d1';mapCtx.lineWidth=5;mapCtx.beginPath();river.forEach((p,i)=>{const x=(p[0]/1500+.5)*w,y=(p[1]/1500+.5)*h;i?mapCtx.lineTo(x,y):mapCtx.moveTo(x,y)});mapCtx.stroke();mapCtx.fillStyle='#479eaa';mapCtx.beginPath();mapCtx.ellipse(( -285/1500+.5)*w,(-105/1500+.5)*h,13,9,-.3,0,Math.PI*2);mapCtx.fill();mapCtx.fillStyle='#dfcaa0';for(const v of villages){const x=(v.x/1500+.5)*w,y=(v.z/1500+.5)*h;mapCtx.fillRect(x-2,y-2,4,4)}mapCtx.fillStyle='#f0cb78';crystals.forEach(c=>{if(!c.collected){const x=(c.group.position.x/1500+.5)*w,y=(c.group.position.z/1500+.5)*h;mapCtx.beginPath();mapCtx.arc(x,y,3,0,Math.PI*2);mapCtx.fill()}});const p=dragon.group.position;const x=(p.x/1500+.5)*w,y=(p.z/1500+.5)*h;mapCtx.save();mapCtx.translate(x,y);mapCtx.rotate(heading);mapCtx.fillStyle='#fff';mapCtx.beginPath();mapCtx.moveTo(0, -5);mapCtx.lineTo(4,4);mapCtx.lineTo(0,2);mapCtx.lineTo(-4,4);mapCtx.closePath();mapCtx.fill();mapCtx.restore()}

const clock=new THREE.Clock();const follow=new THREE.Vector3(0,86,-20),camTarget=new THREE.Vector3();
function updateUI(){const p=dragon.group.position,ground=heightAt(p.x,p.z);document.querySelector('#altitude').innerHTML=`ALT <b>${Math.max(0,Math.round(p.y-ground))}</b> m`;document.querySelector('#coordinates').textContent=`X ${Math.round(p.x)} · Z ${Math.round(p.z)}`;document.querySelector('#speed-value').innerHTML=`${Math.round(speed)} <small>km/h</small>`;document.querySelector('#stamina-value').textContent=`${Math.round(stamina)}%`;document.querySelector('#stamina-bar').style.width=`${stamina}%`;document.querySelector('#health-value').textContent=`${Math.round(health)}%`;document.querySelector('#health-bar').style.width=`${health}%`;document.querySelector('#flight-state').textContent=speed>75?'BOOSTING':p.y-ground<14?'LOW FLIGHT':'CRUISING';const nearest=crystals.find(c=>!c.collected);if(nearest){const d=Math.round(nearest.group.position.distanceTo(p));document.querySelector('#objective-distance').textContent=`${d} m`;if(d<15){nearest.collected=true;scene.remove(nearest.group);collected++;document.querySelector('#quest-progress-fill').style.width=`${collected/3*100}%`;document.querySelector('#quest-progress-text').innerHTML=`${collected} <small>OF 3 EMBERSTONES</small>`;document.querySelector('#objective').querySelector('span:nth-child(2)').textContent=collected<3?'Find the next emberstone':'Return to the old beacon';notify(collected<3?'Emberstone found! The beacon begins to glow.':'All emberstones gathered! The valley beacon is restored.');if(collected===3){document.querySelector('#objective-distance').textContent='COMPLETE';document.querySelector('#region-name').textContent='BEACON RESTORED'} }}else document.querySelector('#objective-distance').textContent='COMPLETE';const v=villages.reduce((a,b)=>Math.hypot(p.x-b.x,p.z-b.z)<Math.hypot(p.x-a.x,p.z-a.z)?b:a,villages[0]);document.querySelector('#region-name').textContent=collected===3?'BEACON RESTORED':v.name;}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04),t=clock.elapsedTime;
if(started){const turn=(keys.KeyA||keys.ArrowLeft?1:0)-(keys.KeyD||keys.ArrowRight?1:0);heading+=turn*dt*(1.15+speed*.006);if(document.pointerLockElement===canvas){heading-=mouseX*.0018;pitch=THREE.MathUtils.clamp(pitch-mouseY*.0012,-.55,.62);mouseX=mouseY=0}if(keys.Space||keys.ArrowUp)pitch=THREE.MathUtils.lerp(pitch,.45,dt*1.6);else if(keys.ControlLeft||keys.KeyC||keys.ArrowDown)pitch=THREE.MathUtils.lerp(pitch,-.42,dt*1.6);else pitch=THREE.MathUtils.lerp(pitch,0,dt*.8);
const boosting=keys.ShiftLeft||keys.ShiftRight;const targetSpeed=boosting&&stamina>0?116:(keys.KeyS?25:58);speed=THREE.MathUtils.damp(speed,targetSpeed,boosting?1.1: .6,dt);if(boosting)stamina=Math.max(0,stamina-dt*18);else stamina=Math.min(100,stamina+dt*8);const forward=new THREE.Vector3(Math.sin(heading),Math.sin(pitch),Math.cos(heading));dragon.group.position.addScaledVector(forward,speed*dt*.48);dragon.group.position.x=THREE.MathUtils.clamp(dragon.group.position.x,-720,720);dragon.group.position.z=THREE.MathUtils.clamp(dragon.group.position.z,-720,720);const floor=heightAt(dragon.group.position.x,dragon.group.position.z)+12;dragon.group.position.y=Math.max(floor,dragon.group.position.y);dragon.group.position.y=THREE.MathUtils.clamp(dragon.group.position.y,0,260);dragon.group.rotation.set(-pitch,heading,Math.sin(turn*dt)*-.09,'YXZ');
for(const w of dragon.wings)w.pivot.rotation.z=w.side*(.18+Math.sin(t*12)*.44);for(const e of enemies){if(!e.alive)continue;e.phase+=dt;const ep=e.dragon.group.position,to=dragon.group.position.clone().sub(ep),dist=to.length();if(dist<190){to.y+=Math.sin(e.phase*2)*8;to.normalize();ep.addScaledVector(to,dt*(dist<40?4:18));e.dragon.group.lookAt(dragon.group.position);e.dragon.wings.forEach(w=>w.pivot.rotation.z=w.side*(.18+Math.sin(t*10+e.phase)*.42));if(dist<24&&hitCooldown<=0){health=Math.max(0,health-8);hitCooldown=1.2;notify('A shadowwing clips Sol! Keep moving.');if(health===0){health=100;dragon.group.position.set(0,90,0);notify('Sol caught his breath back at Sunmeadow.')}}}else{ep.x=THREE.MathUtils.damp(ep.x,e.home.x,1,dt);ep.y=THREE.MathUtils.damp(ep.y,e.home.y+Math.sin(e.phase)*8,1,dt);ep.z=THREE.MathUtils.damp(ep.z,e.home.z,1,dt)}}
